import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import { getBaseURL } from "../apiConfig";
import "./AdminOrderList.scss";

const AdminOrderList = ({ handleOrderDetails, isSeller = false }) => {
  const [orders, setOrders] = useState([]);

  // Stabiliser fetchOrders avec useCallback
  const fetchOrders = useCallback(() => {
    axios
      .get(`${getBaseURL()}api/orders`)
      .then((res) => {
        const allOrders = res.data;
        const filteredOrders = isSeller
          ? allOrders.filter((order) => order.status === "pending")
          : allOrders;
        setOrders(filteredOrders);
      })
      .catch((err) => console.log("Couldn't receive order list:", err));
  }, [isSeller]); // Ajoutez isSeller comme dépendance

  useEffect(() => {
    fetchOrders(); // Appeler fetchOrders au montage
  }, [fetchOrders]); // Inclure fetchOrders comme dépendance

  const validateOrder = (orderId) => {
    axios
      .put(`${getBaseURL()}api/orders/validate/${orderId}`)
      .then(() => {
        alert("Order validated successfully.");
        fetchOrders(); // Rafraîchir la liste des commandes
      })
      .catch((err) => console.log("Couldn't validate order:", err));
  };

  const cancelOrder = (orderId) => {
    axios
      .put(`${getBaseURL()}api/orders/cancel/${orderId}`)
      .then(() => {
        alert("Order canceled successfully.");
        fetchOrders();
      })
      .catch((err) => console.log("Couldn't cancel order:", err));
  };

  const deleteOrder = (orderId) => {
    axios
      .delete(`${getBaseURL()}api/orders/delete/${orderId}`)
      .then(() => {
        alert("Order deleted successfully.");
        fetchOrders();
      })
      .catch((err) => console.log("Couldn't delete order:", err));
  };

  const openOrderDetails = (order) => {
    handleOrderDetails(order);
  };

  return (
    <div>
      <h1>Order List</h1>
      <table>
        <thead>
          <tr>
            <th>Id</th>
            <th>Customer Name</th>
            <th>Order Date</th>
            <th>Price</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((order) => (
            <tr key={order.orderId}>
              <td>{order.orderId}</td>
              <td>{order.fname}</td>
              <td>{order.createdDate}</td>
              <td>{order.totalPrice}</td>
              <td>{order.status}</td>
              <td>
                <button onClick={() => openOrderDetails(order)}>Details</button>

                {order.status === "pending" && (
                  <>
                    <button onClick={() => validateOrder(order.orderId)}>
                      Validate
                    </button>
                    <button onClick={() => cancelOrder(order.orderId)}>
                      Cancel
                    </button>
                  </>
                )}

                {!isSeller && (
                  <button onClick={() => deleteOrder(order.orderId)}>
                    Delete
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default AdminOrderList;
